const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=v=>v===null||v===undefined?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(v);
const names={creatives:'AIGC 图文改进',products:'商品与广告',trials:'商品利润实验',home:'店铺总览',stores:'店铺管理',migration:'商品迁移',reviews:'客户沟通',gates:'确认队列',market:'市场评估',audit:'操作证据'};
const stages={extract:'提取',translate:'翻译适配',image_edit:'图片处理',map_attributes:'类目映射',validate:'校验',review_gate:'人工确认',submitted:'已提交 · 待导入',imported:'已导入 · 查看审核',published:'已模拟发布',synced:'已模拟同步',running:'执行中',publishing:'提交中',needs_input:'需要补充'};
let creativeTimer;let wbTrialTimer,wbTrialTicket=0;
let ozonStatusTimer=null,ozonPollScope=null,ozonPollCount=0;
let state={wbEconomics:{},wbBulkDrafts:{},wbTrialEvidence:{},wbAllocationDrafts:{},page:'home',homeStore:'ozon-live',productStore:'ozon-live',productScope:'activity',focus:null,catalogue:{},data:null,job:null,live:null,digest:null,assessment:null,benchmark:null,wbRequirements:null,dictionary:null,busy:false};let wbErrorsTimer,wbErrorsScope=null,wbErrorsTicket=0,wbAdsTimer,wbAdsScope=null,wbAdsTicket=0,wbFinanceTimer,wbFinanceScope=null,wbFinanceTicket=0,financeTimer,liveTimer,catalogueTimer,inventoryTimer,inventoryRequest=0,catalogueRequest=0;
async function api(path='',body){const r=await fetch('/api/workspace'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':body instanceof Blob?(body.type||'application/octet-stream'):'application/json'},body:body instanceof Blob?body:JSON.stringify(body)});let d;try{d=await r.json();}catch{throw Error('本地服务未启动；公开 GitHub Pages 不提供私有 API。');}if(!r.ok)throw Error(d.error||'请求失败');return d;}
function say(text,bad=false){$('#notice').textContent=text;$('#notice').className=bad?'error':'success';}
async function load(){state.data=await api();state.digest=await api('/digest');scheduleFinance();scheduleCreatives();}
async function action(fn,message){if(state.busy)return;const page=state.page,jobId=state.job?.id,openFinance=[...document.querySelectorAll('details[id]')].filter(d=>d.open).map(d=>d.id);let failed=false;state.busy=true;say('正在处理，请稍候…');document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();await load();say(message||'已更新');}catch(e){failed=true;say(e.message,true);try{await load();}catch{}}finally{const keep=failed&&page===state.page&&jobId===state.job?.id,forms=keep?captureForms($('#portal')):null,linked=keep?$('#linked-plan')?.textContent:null;state.busy=false;render();if(page===state.page)for(const id of openFinance){const d=document.getElementById(id);if(d)d.open=true;}if(forms){restoreForms($('#portal'),forms);if(linked&&$('#linked-plan'))$('#linked-plan').textContent=linked;}}}

function badge(mode){return `<span class="badge ${mode==='live'?'live':'mock'}">${mode==='live'?'真实 API':mode==='manual'?'人工导出':mode==='sample'?'AI 实测 · 合成商品':'DEMO · 模拟'}</span>`;}
function storeOptions(mockOnly=false){return state.data.stores.filter(s=>!mockOnly||s.mode==='mock').map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${s.marketplace.toUpperCase()} · ${s.mode==='live'?'API':'DEMO'}</option>`).join('');}
function storeName(id){return state.data.stores.find(s=>s.id===id)?.name||id;}
function home(){if(!state.data.stores.some(s=>s.id===state.homeStore&&s.mode==='live'))state.homeStore=state.data.stores.find(s=>s.mode==='live')?.id;return storeHome({...state.data,wbAllocationDrafts:state.wbAllocationDrafts,wbBulkDrafts:state.wbBulkDrafts,wbEconomics:state.wbEconomics},state.live,state.homeStore);}
function stores(){return `${connectionPanel()}<div class="intro"><h2>店铺、连接与同步</h2><p>每家店铺独立读取；演示店铺不计入经营总览。</p></div>${marketplaceRoadmap(state.data.marketplaces,state.data.stores)}${wbRequirementsPanel()}<div class="section-head"><h2>我的店铺</h2><span class="muted">真实 API 与演示环境隔离</span></div><div class="store-grid">${state.data.stores.map(s=>`<article class="card store"><div class="section-head"><span class="platform ${s.marketplace}">${s.marketplace==='wb'?'WB':'OZON'}</span>${badge(s.mode)}</div><h3>${esc(s.name)}</h3><p>${s.mode==='live'?(s.marketplace==='ozon'?(s.id==='ozon-live'?'Ozon 新商品、RUB 价格与指定 SKU 的 CPO 启停需确认；库存写入关闭':'Ozon 新商品与 RUB 价格需确认；广告控制与库存写入未接入'):'WB '+(s.wbRegion==='cn'?'中国站':'俄罗斯站')+' · 读取目录、价格、库存、财务与广告；卡片、图片、原币种价格及卖家仓库库存需确认后提交'):'完整模拟流程 · 不会改变真实店铺'}</p><div class="store-values"><div><small>已读取商品</small><b>${state.data.catalogueStatus?.[s.id]?.loaded!=null?`${state.data.catalogueStatus[s.id].loaded}${state.data.catalogueStatus[s.id].complete?'':' / '+(state.data.catalogueStatus[s.id].total??'未知')}`:s.snapshot?.catalogTotal??s.snapshot?.products?.length??'—'}</b></div><div><small>订购金额</small><b>${rub(s.snapshot?.orderedAmount)}</b></div></div><div class="actions"><button class="quiet" data-nav="products" data-product-store="${s.id}">查看商品</button><button class="quiet" data-sync="${s.id}">同步数据</button><button class="quiet" data-dictionary="${s.id}">类目字典</button><button class="quiet" data-demo-review="${s.id}" ${s.mode==='live'?'disabled':''}>演示评价</button></div>${s.snapshot?`<small class="muted">${esc(s.snapshot.source)}</small>`:''}</article>`).join('')}</div><details class="card"><summary>添加店铺 / 配置真实连接</summary><form id="store-form" class="form-grid"><label>店铺名称<input name="name" required maxlength="80"></label><label>平台<select name="marketplace"><option value="ozon">Ozon</option><option value="wb">Wildberries</option></select></label><button class="primary">添加演示店铺</button></form><p class="muted">真实连接由本机 connection.json 中的 stores 配置加载；密钥只存服务端。WB 需要独立 API token；中国站连接配置 wbRegion 为 cn，俄罗斯站为 ru。这里不会要求你把密钥放入商品或聊天记录。</p></details>${state.dictionary?`<section class="card"><h3>类目字典 ${badge(state.dictionary.mode)}</h3><p class="muted">${esc(state.dictionary.source)} · ${state.dictionary.items.length} 条${state.dictionary.truncated?'（已截断）':''}</p><div class="dictionary-list">${state.dictionary.items.slice(0,30).map(c=>`<p><code>${esc(c.id||c.subjectID)}</code> ${esc(c.name||c.subjectName)}</p>`).join('')}</div></section>`:''}<section class="card"><div class="section-head"><h2>今日摘要</h2><button class="quiet" id="digest-refresh">刷新摘要</button></div>${state.digest?.stores.map(s=>`<p>${badge(s.mode)} <b>${esc(s.name)}</b> · 待处理 ${s.pending} · 已加载低库存 ${s.lowStock?.length??'—'} · 已加载待处理低分评价 ${s.negativeReviews??'—'}</p>`).join('')}<p class="muted">按需生成；无定时推送。未接入的退货、评分趋势和投诉不视为零。</p>${state.digest?.alerts.map(a=>`<p class="warning">${esc(a.message)}</p>`).join('')}</section><details class="card"><summary>演示工具 · 价格与库存</summary><form id="ops-form"><div class="form-grid"><label>店铺<select name="storeId">${storeOptions(true)}</select></label><label>操作<select name="kind"><option value="stock">库存</option><option value="price">价格（RUB）</option></select></label><label>SKU<input name="sku" required value="DEMO-STORAGE-01"></label><label>新值<input name="target" required type="number" min="0" value="48"></label></div><details><summary>价格保护参数（调价时必填）</summary>${economyFields('op',false)}<label>最低毛利率 %<input name="minMarginPct" type="number" min="0" max="90" value="15"></label></details><button class="primary">生成待确认操作</button></form><p class="muted">成本与费用统一填写 RUB；未知成本不能当作零。真实价格请从“商品利润实验”准备；此表仅演示价格/库存操作。</p></details>`;}
function wbRequirementsPanel(){const stores=state.data.stores.filter(s=>s.marketplace==='wb'&&s.mode==='live'),r=state.wbRequirements;return `<details class="card" ${r?'open':''}><summary>WB 类目必填特征 · 真实 API</summary>${stores.length?`<form id="wb-requirements" class="form-grid"><label>WB 店铺<select name="storeId">${stores.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label>类目 ID（从类目字典获取）<input name="subjectId" type="number" min="1" step="1" required></label><button class="quiet">读取必填特征</button></form>`:'<p>请先配置 WB 店铺及 Content API token。DEMO 字典不是平台实时要求。</p>'}${r?`<p>${esc(storeName(r.storeId))} · ${esc(r.subjectName)} · ${r.requiredCount} 个必填字段 · ${esc(r.fetchedAt)}</p><div class="table-wrap"><table><thead><tr><th>特征</th><th>必填</th><th>单位</th></tr></thead><tbody>${r.items.map(a=>`<tr><td>${esc(a.name)} · ${a.id}</td><td>${a.required?'是':'否'}${a.hasFilter?' · 筛选特征':''}</td><td>${esc(a.unit)}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="muted">只读取要求；值字典、商品准入和认证仍需核验。创建文字卡片请进入商品迁移；图片可通过独立确认流程上传，完整开售状态仍需核验。</p></details>`;}
function benchmarkPanel(){const b=state.benchmark;return `<section class="card"><div class="section-head"><h2>实测证据</h2><button class="quiet" id="benchmark-load">更新测量数据</button></div><p class="muted">仅成功工具调用耗时（含重跑），不含失败调用、人工等待与平台审核。标题和描述仅为两个字段，不代表全部内容。</p>${b?`<div class="table-wrap"><table><thead><tr><th>样本来源</th><th>任务 / 有耗时记录</th><th>累计机器耗时</th><th>曾修改文本字段 / 已测字段</th></tr></thead><tbody>${Object.entries(b.summary).map(([k,v])=>`<tr><td>${({synthetic_ai:'合成商品 · 真实 AI',fixture_demo:'固定 DEMO',seller_export:'卖家导出 · 来源未独立核实'})[k]}</td><td>${v.jobs} / ${v.timedJobs}</td><td>${v.successfulToolMs===null?'未测量':(v.successfulToolMs/1000).toFixed(1)+' 秒'}</td><td>${v.textFieldsEverChanged} / ${v.textFieldsMeasured}</td></tr>`).join('')}</tbody></table></div><p>完整上架时间、首轮审核通过率、每 SKU 金额成本：尚未测量。10 个真实 SKU、≤10 分钟、≥80% 字段无需修改均为目标。</p><button class="quiet" id="benchmark-export">下载测量证据 JSON</button>`:'<p>点击更新，从本地阶段记录与版本历史计算；不会将模拟发布算作真实上架。</p>'}</section>`;}
function migration(){const step=!state.job?1:["submitted","imported","published","synced"].includes(state.job.state)?3:2;return `<ol class="transfer-steps" aria-label="迁移进度">${["上传商品页","核对商品与价格","提交 Ozon"].map((label,i)=>`<li class="${i+1===step?'current':i+1<step?'done':''}" ${i+1===step?'aria-current="step"':''}><b>${i+1}</b>${label}</li>`).join('')}</ol>${state.job?`<details id="transfer-another"><summary>导入另一件商品</summary>${pageImportPanel(storeOptions(),state.pageImport)}</details>`:pageImportPanel(storeOptions(),state.pageImport)}${state.job?jobDetail(state.job):''}<details id="transfer-tools"><summary>其他导入方式与测试</summary><section class="card"><div class="section-head"><h2>导入商品</h2><span class="badge mock">Taobao API 未配置 · 可用结构化导出</span></div><form id="import-form"><div class="form-grid"><label>目标店铺<select name="storeId">${storeOptions()}</select></label><label>淘宝 / 天猫商品链接<input name="sourceUrl" type="url" placeholder="https://item.taobao.com/item.htm?id=…"></label></div><label>商品结构化导出 JSON<textarea name="product" rows="4" placeholder='{"sku":"…","titleZh":"…","descriptionZh":"…","categoryZh":"…","price":35,"currency":"CNY","sourceUrl":"https://…","images":[]}'></textarea></label><div class="actions"><button class="primary">导入导出文件内容</button><button class="quiet" type="button" id="import-demo">运行示例商品（隔离 DEMO）</button><button type="button" class="primary" id="import-ai-sample">用订阅运行 AI 测试商品</button></div><p class="muted">链接本身不能绕过淘宝授权。没有 API 或导出时，不会声称抓取成功。DEMO 使用固定译文；AI 测试使用合成商品和真实 Codex 翻译/OCR，消耗订阅额度，不能发布到真实店铺。</p></form></section></details><details id="transfer-history"><summary>历史迁移 · ${state.data.jobs.length} 件</summary><section class="card"><h2>迁移队列 <span class="muted">${state.data.jobs.length}</span></h2>${state.data.jobs.length?`<div class="table-wrap"><table><thead><tr><th>商品</th><th>店铺</th><th>当前阶段</th><th>版本</th><th></th></tr></thead><tbody>${state.data.jobs.slice(-50).reverse().map(j=>`<tr><td>${esc(j.title)}<small>${badge(j.mode)}</small></td><td>${esc(storeName(j.storeId))}</td><td>${esc(stages[j.state]||j.state)}</td><td>v${j.revision}</td><td><button class="quiet" data-job="${j.id}">查看</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">还没有商品。先导入一件，验证流程。</p>'}</section></details><details id="transfer-evidence"><summary>耗时与运行证据</summary>${benchmarkPanel()}</details>`;}
function jobDetail(j){const a=j.artifacts,tr=a.translate?.output,ma=a.map_attributes?.output,missing=j.failedStage==='validate'?[!Number(j.publishConfig?.price)&&'销售价格',!j.publishConfig?.rightsConfirmed&&'商品与图片使用权确认',!j.publishConfig?.complianceConfirmed&&'所需文件与平台限制核对',!j.publishConfig?.imagesReviewed&&'图片核对'].filter(Boolean):[];return `${wbLaunchPanel(j,state.data.operations,state.data.stores.find(s=>s.id===j.storeId)?.wbRegion)}<section class="card job-detail"><div class="section-head"><div><span class="eyebrow">${esc(j.canonical.sku)} · ${esc(storeName(j.storeId))}</span><h2>${esc(j.canonical.titleZh)}</h2></div>${badge(j.mode)}</div><details id="transfer-stages"><summary>处理进度 · ${esc(stages[j.pendingStage||j.failedStage||j.state]||j.state)}</summary><div class="pipeline">${['extract','translate','image_edit','map_attributes','validate','review_gate','published','synced'].map((s,i)=>`<div class="${a[s]||s==='review_gate'&&j.gates.category||s==='published'&&j.receipt||s==='synced'&&j.state==='synced'?'done':j.state===s?'current':''}"><b>${i+1}</b><span>${s==='published'&&j.mode!=='mock'?'API 提交':s==='synced'&&j.mode!=='mock'?'读取核对':stages[s]}</span></div>`).join('')}</div></details>${j.error?`<p class="warning">${esc(missing.length?'请补充：'+missing.join('、'):j.error)}</p>`:''}<div class="actions">${(j.state==='running'||j.state==='needs_input'&&j.failedStage!=='validate')?'<button class="quiet" id="retry-stage">重启此阶段（恢复中断）</button>':''}${!['review_gate','running','publishing','submitted','imported','published','synced'].includes(j.state)?`<button class="primary" id="next-stage">${j.failedStage==='validate'?'补充发布资料':'继续处理商品'}</button>`:''}${j.state==='review_gate'&&j.marketplace==='ozon'&&j.mode==='manual'?`<div><p>${esc(storeName(j.storeId))} · ${esc(j.publishConfig?.price)} ${esc(j.publishConfig?.currency)} · 新建商品卡片</p><button class="primary" id="submit-ozon-card">提交这张卡片到 Ozon</button></div>`:j.state==='review_gate'?`<button class="primary" id="approve-category" ${j.gates.category?.revision===j.revision?'disabled':''}>确认商品资料</button><button class="quiet" id="prepare-publish" ${j.gates.category?.revision!==j.revision?'disabled':''}>查看提交预览</button>`:''}${(['published','submitted','imported'].includes(j.state)||j.marketplace==='wb'&&j.state==='publishing')?'<button class="primary" id="sync-published">查询发布 / 审核状态</button>':''}</div>${j.marketplace==='ozon'&&j.importResult?`<button class="quiet" id="inspect-ozon-listing">检查买家内容与配送配置</button>${j.listingCheck?`<section class="target"><h3>平台实际内容与可售状态</h3><p>${esc(j.listingCheck.title)} · ${esc(j.listingCheck.price)} ${esc(j.listingCheck.currency)}</p><p>${esc(j.listingCheck.description||'描述未取得')}</p><div class="source-photo-grid">${j.listingCheck.images.map(u=>`<img src="${esc(u)}" alt="Ozon 已保存的图片">`).join('')}</div><p>库存：${j.listingCheck.present===null?(j.listingCheck.hasStock===false?'0（无可售库存）':'待核对'):j.listingCheck.present} · 仓库：${j.listingCheck.warehouses.length} · 配送方式：${j.listingCheck.deliveryMethods.length}</p>${j.listingCheck.blockers.map(b=>`<p class="warning">${esc(({no_stock:'当前没有可售库存，不能下单',no_warehouse:'尚未取得已配置仓库',no_delivery_method:'没有已配置配送方式'})[b]||b)}</p>`).join('')}<details id="transfer-delivery-details"><summary>配送配置与读取结果</summary><pre>${esc(JSON.stringify(j.listingCheck,null,2))}</pre></details></section>`:''}`:''}${listingEditor(j)}${j.importResult?j.marketplace==='wb'?`<section class="target"><h3>${j.importResult.imported?'已读取到 WB 卡片':'WB 创建待核对'}</h3><p>${esc(j.importResult.message)}</p>${j.importResult.productId?`<p>nmID ${esc(j.importResult.productId)} · 已读取图片数 ${j.importResult.photosCount??'未知'}</p>`:''}<p class="muted">尚未核实平台审核与开售状态。</p></section>`:`<section class="target"><h3>${j.importResult.imported?'Ozon 已接收商品资料':'Ozon 正在处理'}</h3><p>平台状态：${esc([j.importResult.platformStatus?.status_name,j.importResult.platformStatus?.status_description].filter(Boolean).join(' · ')||j.importResult.status)}${j.importResult.productId?' · Seller API ID '+esc(j.importResult.productId):''}</p>${(j.imageRepair?.state==='verified'?[]:j.importResult.errors||[]).map(e=>`<p class="warning">${esc(e.message||e.description||e.code||JSON.stringify(e))}</p>`).join('')}${j.importResult.buyerUrl?`<p><a href="${esc(j.importResult.buyerUrl)}" target="_blank" rel="noopener">打开 Ozon 买家卡片</a> · SKU ${esc(j.importResult.buyerSkus?.join(', '))}</p>`:''}<p>售价：${esc(j.livePrice?.price||j.listingCheck?.price||j.publishConfig?.price)} ${esc(j.livePrice?.currency||j.listingCheck?.currency||j.publishConfig?.currency)}</p><p class="muted">${j.importResult.moderationVerified?'平台审核已通过。':'平台审核状态待核对。'}${j.listingCheck?.present!==null&&j.listingCheck?.present!==undefined?'平台库存：'+esc(j.listingCheck.present):j.liveStock?.accepted?'库存已提交：'+esc(j.liveStock.quantity)+'，请读取核对':'可售库存尚未确认。'}</p>${(j.importResult.errors||[]).length&&j.marketplace==='ozon'&&!j.imageRepair?.state?.match(/uploading|submitting|accepted|unknown|verified/)?'<button class="primary" id="repair-ozon-images">修复图片下载</button>':''}${j.importResult.imageCount?`<p>平台已读取图片：${j.importResult.imageCount} 张</p>`:''}${j.imageRepair?`<p>图片修复：${esc(({uploading:'正在上传',submitting:'正在提交',accepted:'已提交',verified:'已核对',unknown:'结果待核对',blocked:'需处理'})[j.imageRepair.state]||j.imageRepair.state)}${j.imageRepair.error?' · '+esc(j.imageRepair.error):''}</p>`:''}<details id="transfer-platform-receipt"><summary>平台回执</summary><pre>${esc(JSON.stringify(j.importResult,null,2))}</pre></details></section>`:''}${tr?`<details id="transfer-source"><summary>查看中文原文</summary><div class="source"><span>原文 · 中文</span><h3>${esc(j.canonical.titleZh)}</h3><p>${esc(j.canonical.descriptionZh)}</p><pre>${esc(JSON.stringify(j.canonical.attributes,null,2))}</pre></div></details><div class="target"><span>${j.state==='imported'?'首次提交快照 · v':'俄语草稿 · v'}${j.translationVersion}</span><form id="edit-draft"><label>俄语标题<input name="title" value="${esc(tr.title)}" required></label><label>俄语描述<textarea name="description" rows="5" required>${esc(tr.description)}</textarea></label><button class="quiet" ${['publishing','submitted','imported','published','synced'].includes(j.state)?'disabled':''}>保存修改</button></form><p class="muted">修改会撤销旧审批；源文本不变。</p></div>`:''}${j.marketplace==='ozon'&&tr&&!a.image_edit?`<section class="photo-choice"><h3>商品图片</h3><p>保留原始照片，或按需要处理图中文字。</p><div class="source-photo-grid">${j.canonical.images.map(im=>`<img src="/api/workspace/assets/${esc(im.assetId)}" alt="商品原图">`).join('')}</div><button class="quiet" id="keep-source-images">使用这些原图</button></section>`:''}${a.image_edit?`<h3>商品图片 <span class="badge mock">${j.mode==='mock'?'模板演示':a.image_edit.output.mode==='source_original'?'原图 · 未修改':'已处理 · 请检查图片'}</span></h3><div class="source-photo-grid">${a.image_edit.output.images.map(im=>`<img src="${esc(im.assetId?'/api/workspace/assets/'+im.assetId:im.url)}" alt="${a.image_edit.output.mode==='source_original'?'商品原图':'处理后的商品图片'}">`).join('')}</div>${a.image_edit.output.mode==='source_original'?'<p class="muted">原图上的中文、品牌标识与水印均保留，请核对使用权和平台要求。</p>':''}`:''}${ma?`<p class="muted">商品分类：${esc(ma.category.name)}${ma.schema?' · 已核对 Ozon 必填属性':''}</p>`:''}${a.validate?`<h3>校验结果</h3>${a.validate.output.issues.map(i=>`<p class="${i.level==='error'?'warning':'muted'}">${esc(i.message)}</p>`).join('')}`:''}<details id="transfer-calls"><summary>工具调用与证据</summary>${Object.entries(a).map(([k,v])=>`<p><b>${esc(v.agent)}</b> · ${esc(v.tool)} · ${v.durationMs}ms${v.provider?` · ${esc(v.provider)}`:''}${v.usage?` · tokens ${v.usage.input_tokens??'—'} / ${v.usage.output_tokens??'—'}`:''}<br><code>${esc(v.outputHash)}</code></p>`).join('')}<p class="muted">${j.evidence.length} 个证据记录 · 完整状态保存在服务器</p></details></section>${wbMediaPanel(j,state.data.operations)}${wbJobPricePanel(j)}${wbJobStockPanel(j)}${setupPanel(j)}`;}
function reviews(){return `<section class="card"><div class="section-head"><h2>评价与买家提问</h2><form id="review-sync" class="inline"><select name="storeId">${storeOptions()}</select><button class="quiet">同步 API</button></form></div><p class="muted">真实评价按权限读取；可用 Codex 订阅生成中文翻译与俄语回复草稿。生成后仍需人工确认，真实发送尚未启用。手机号与邮箱先掩码。</p>${state.data.reviews.length?state.data.reviews.map(r=>`<article class="review"><div class="section-head"><span>${badge(r.mode)} ${esc(storeName(r.storeId))}</span><span>${r.rating===null?'提问':r.rating+' ★'} · ${r.status==='answered'?'已模拟回复':'待处理'}</span></div><div class="diff-grid"><div><small>俄文原文</small><p>${esc(r.textRu)}</p></div><div class="target"><small>中文理解</small><p>${esc(r.textZh)}</p></div></div><div class="actions"><button class="quiet" data-ai-review="${r.id}" ${r.status==='answered'?'disabled':''}>AI 翻译并起草（订阅）</button><button class="quiet" data-review-creative="${esc(r.id)}">用这条评价改进图文 →</button><small>${esc(r.aiDraft?.state||'')}</small></div>${(r.aiDraft?.warnings||[]).map(w=>`<p class="warning">${esc(w)}</p>`).join('')}<form data-reply="${r.id}" data-store="${r.storeId}"><label>俄语回复草稿<textarea name="reply" rows="3" required>${esc(r.reply||r.draftRu)}</textarea></label><button class="primary" ${r.status==='answered'?'disabled':''}>③ 翻译此回复并提交确认</button></form></article>`).join(''):'<p class="empty">暂无评价。可在店铺管理给演示店铺加入一条模拟评价。</p>'}</section>`;}
function gates(){return `<div class="intro"><h2>每个外部动作，都由你确认</h2><p>核对店铺、内容和变更，再确认该版本。确认后仍需执行。Ozon 支持商品创建、RUB 价格计划及指定 SKU 的 CPO 启停；WB 支持确认后创建卡片、上传俄语图片、调价及设置卖家仓库库存；API 接受不等于审核通过或利润提高。</p></div>${state.data.operations.length?state.data.operations.slice().reverse().map(o=>o.kind==='wb_stock'?wbStockGate(o,storeName(o.storeId)):o.kind==='wb_price'?wbPriceGate(o,storeName(o.storeId)):o.kind==='wb_media'?wbMediaGate(o,storeName(o.storeId)):`<section class="card" id="operation-${esc(o.id)}"><div class="section-head"><h3>${o.kind==='publish'&&o.payload.marketplace==='wb'?'创建 WB 商品卡片':({cpo_enable:'开启指定商品 CPO',cpo_disable:'关闭指定商品 CPO',publish:'发布商品',price:'修改价格',stock:'修改库存',reply:'回复买家'})[o.kind]} · ${esc(storeName(o.storeId))}</h3>${badge(o.mode)}</div><p class="muted">${esc(({pending:'待确认',approved:'已确认 · 待执行',executing:'提交中',submitted:'API 已接受 · 待核对',verified:'已读取核对',blocked:'已停止 · 需重新拟定',unknown:'结果不确定',done:'模拟完成',superseded:'旧版本已失效'})[o.state]||o.state)} · ${esc(o.createdAt)}</p>${['cpo_disable','cpo_enable'].includes(o.kind)?cpoGate(o):o.kind==='publish'?`<div class="diff-grid"><div><small>发布前</small><p>创建新商品卡片；发送前再次查询货号。</p>${o.payload.marketplace==='wb'?'<p class="warning">WB 此次仅创建文字、特征、包装与尺码。图片、价格和库存未发送，平台审核与开售状态仍需核对。可用免费额度与货号已读取；确认有效期 15 分钟。</p>':''}</div><div class="target"><small>发布后草稿 · RU</small><h3>${esc(o.payload.title)}</h3><p>${esc(o.payload.description)}</p><p>${esc(o.payload.category.name)}</p>${o.payload.marketplace==='wb'?wbPublicationPreview(o.payload):''}${o.payload.apiBody?`<details><summary>实际发送内容（完整字段）</summary><pre>${esc(JSON.stringify(o.payload.apiBody,null,2))}</pre></details>`:''}</div></div>`:o.kind==='reply'?`<div class="diff-grid"><div><small>买家消息 · RU / 中文理解</small><p>${esc(o.payload.sourceRu||'旧版本缺少源消息，请重新拟定')}</p><p>${esc(o.payload.sourceZh||'待核对翻译')}</p></div><div class="target"><small>将发送的俄语内容</small><p>${esc(o.payload.reply)}</p><small>此版本回复的中文翻译 · 请核对承诺</small><p>${esc(o.payload.replyZh||'旧版本缺少翻译，请重新提交回复确认')}</p></div></div>`:`<div class="change"><span>${esc(o.payload.sku)}</span><b>${o.payload.before===null?'旧值未读取':esc(o.payload.before)} → ${esc(o.payload.target)} ${o.payload.currency||'шт.'}</b>${o.payload.economics?`<span>假设贡献利润率 ${o.payload.economics.marginPct}%</span>`:''}</div>`}${o.kind==='price'&&o.payload.context?`<p class="warning">修改的是 Ozon 不含促销的价格上限，不是买家最终成交价。平台其他策略保持不变；系统不会自动回滚或停止实验。</p><p>平台核对 ${esc(o.payload.context.checkedAt)} · 15分钟内确认有效 · 成本保护底价 ${rub(o.payload.minimumPrice)} · 当前划线价 ${rub(o.payload.context.oldPrice)}</p><details><summary>将提交的价格、税率与保留设置</summary><pre>${esc(JSON.stringify(o.payload.apiBody,null,2))}</pre></details>${o.priceObservation?`<p>最近读取价格 ${rub(o.priceObservation.price)} · ${esc(o.priceObservation.at)} · ${o.priceObservation.matches?'与目标一致':'尚未匹配目标'}${o.priceObservation.originProven?'':'；无法证明是本次操作导致'}</p>`:''}`:''}<code class="hash">版本指纹 ${esc(o.payloadHash)}</code><div class="actions">${o.state==='pending'?`<button class="primary" data-approve="${o.id}">确认此版本</button>`:''}${o.state==='approved'?`<button class="primary" data-execute="${o.id}" ${o.mode==='live'&&o.kind!=='publish'&&!(['price','cpo_disable','cpo_enable'].includes(o.kind)&&o.payload.planId)?'disabled':''}>执行${o.mode==='mock'?'模拟动作':['cpo_disable','cpo_enable'].includes(o.kind)?'向 Ozon 提交已确认 CPO '+(o.payload.target?'开启':'关闭'):o.kind==='price'?'向 Ozon 提交已确认价格':'向 '+(o.payload.marketplace==='wb'?'WB 创建':'Ozon 提交')+'已确认商品'}</button>`:''}${o.state==='done'?`<span class="badge mock">模拟执行成功 · 未发送到平台</span>`:''}${o.state==='submitted'?`<span class="badge live">${['cpo_disable','cpo_enable'].includes(o.kind)?'API 已接受 CPO 变更；请读取状态核对':o.kind==='price'?'API 已接受价格；请读取核对':'已提交 API；请在商品页查询导入与审核状态'}</span>`:''}${o.state==='verified'?'<span class="badge live">API 已读取到匹配状态；不代表审核通过或盈利改善</span>':''}${o.state==='blocked'?`<p class="warning">${esc(o.error)} · 请重新拟定</p>`:''}${['cpo_disable','cpo_enable'].includes(o.kind)&&(['submitted','unknown','verified'].includes(o.state)||o.state==='blocked'&&o.receipt?.status==='not_updated')?`<button class="quiet" data-cpo-status="${o.id}">读取 CPO 状态核对</button>`:''}${o.kind==='price'&&['submitted','unknown','verified'].includes(o.state)?`<button class="quiet" data-price-status="${o.id}">读取平台价格核对</button>`:''}${o.state==='superseded'?'<span class="muted">已被新版本替代，旧确认失效</span>':''}${o.state==='unknown'?'<span class="warning">结果不确定，禁止自动重试</span>':''}</div></section>`).join(''):'<section class="card empty">暂无待确认动作。先迁移商品或生成价格、库存、回复计划。</section>'}`;}
function creatives(){return creativePage(state.data);}
function market(){return assessmentPage(state.assessment||state.data.assessments.at(-1));}
function auditPage(){return `<section class="card"><div class="section-head"><h2>可追溯的工具调用</h2><span class="badge ${state.data.auditValid?'live':'mock'}">${state.data.auditValid?'哈希链校验通过':'哈希链异常'}</span></div><p class="muted">记录输入与输出哈希、阶段、审批和回执。不在日志中存 API 密钥或买家手机号。</p><div class="table-wrap"><table><thead><tr><th>时间</th><th>事件</th><th>阶段 / 工具</th><th>证据哈希</th></tr></thead><tbody>${state.data.audit.slice().reverse().map(a=>`<tr><td>${esc(a.time)}</td><td>${esc(a.kind)}</td><td>${esc(a.agent||a.stage||a.operation||'—')}</td><td><code title="${esc(a.hash)}">${esc(a.hash.slice(0,20))}…</code></td></tr>`).join('')}</tbody></table></div></section>`;}
function render(){if(!state.data)return;if(state.page==='migration'&&state.job)history.replaceState(null,'','#migration/'+encodeURIComponent(state.job.id));const wbOpen=[...document.querySelectorAll('details[id][open]')].map(d=>d.id);$('#title').textContent=names[state.page];$('#gate-count').textContent=state.data.operations.filter(o=>o.state==='pending').length||'';document.querySelectorAll('[data-page]').forEach(b=>{b.disabled=state.busy;b.classList.toggle('active',b.dataset.page===state.page);});$('#portal').innerHTML=({products:()=>skuEconomy(state.live,state.data,state.productStore,state.catalogue,skuFocus(state.data,state.live,state.focus),state.productScope)+costsPanel(state.data,state.productStore),trials:()=>trialsPage({...state.data,wbTrialEvidence:state.wbTrialEvidence,wbAllocationDrafts:state.wbAllocationDrafts}),home,stores,creatives,migration,reviews,gates,market,audit:auditPage}[state.page])();for(const id of wbOpen){const d=document.getElementById(id);if(d)d.open=true;}bind();}
async function openJob(id){if(state.busy)return;await action(async()=>{const job=await api('/jobs/'+encodeURIComponent(id));state.job=job;state.page='migration';},'已打开商品；未提交任何变更');if(state.page==='migration'&&state.job?.id===id)document.querySelector('.wb-launch,.job-detail')?.scrollIntoView({behavior:'smooth',block:'start'});}
function navigate(page){state.page=page;say('');render();window.scrollTo(0,0);if(page==='products'){loadCatalogue();loadWbPrices();loadWbInventory();loadWbFinance();loadWbAds();}else{clearTimeout(catalogueTimer);clearTimeout(inventoryTimer);}}
async function loadWbTrialEvidence(id){const ticket=++wbTrialTicket,ids=id?[id]:Object.keys(state.wbTrialEvidence);for(const key of ids){const value=await api('/trial-plans/'+encodeURIComponent(key)+'/wb-evidence');if(ticket!==wbTrialTicket)return;state.wbTrialEvidence[key]=value;}}
function scheduleWbTrials(){clearTimeout(wbTrialTimer);if(state.page!=='trials'||!Object.values(state.wbTrialEvidence).some(v=>Object.values(v.periods).some(p=>['finance','ads'].some(k=>['waiting','reading'].includes(p[k].state)))))return;wbTrialTimer=setTimeout(async()=>{if(state.page!=='trials'||state.busy){scheduleWbTrials();return;}try{await loadWbTrialEvidence();if(state.page==='trials'&&!state.busy){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}}catch(e){say(e.message,true);}finally{scheduleWbTrials();}},3000);}
