function scheduleCreatives(){
 clearTimeout(creativeTimer);
 if(state.data?.creatives?.some(c=>['queued','generating'].includes(c.state)))creativeTimer=setTimeout(pollCreatives,3000);
}
async function pollCreatives(){
 if(state.busy){scheduleCreatives();return;}
 try{const rows=await api('/creatives');if(state.busy){scheduleCreatives();return;}state.data.creatives=rows;if(state.page==='creatives'){refreshCreativeCards(state.data);bindCreatives({data:state.data,api,action});}}
 catch{say('图文进度暂时无法读取；后台任务可能仍在运行，请勿重复提交。',true);}
 scheduleCreatives();
}
function scheduleFinance(){
 clearTimeout(financeTimer);
 if([...(state.data?.financeReadings||[]),...(state.data?.adReadings||[])].some(r=>['queued','running'].includes(r.state)))financeTimer=setTimeout(pollFinance,3000);else if(state.data?.adMonitors?.some(m=>m.enabled))financeTimer=setTimeout(pollFinance,60000);
}
async function pollFinance(){
 try{
  const d=await api(),changed=JSON.stringify([d.financeReadings,d.adReadings,d.adMonitors])!==JSON.stringify([state.data.financeReadings,state.data.adReadings,state.data.adMonitors]);
  state.data.adMonitors=d.adMonitors;state.data.adMonitorWorker=d.adMonitorWorker;state.data.adReadings=d.adReadings;state.data.financeReadings=d.financeReadings;state.data.trials=d.trials;
  if(changed&&!state.busy&&['home','products','trials'].includes(state.page)){
   const root=$('#portal'),forms=captureForms(root),query=$('#sku-query')?.value;
   const open=[...root.querySelectorAll('.plan-details,.plan-finance,.plan-ads,.trial-history,.plan-history,.wb-contribution,.wb-allocation,.wb-sku-contribution,.wb-bulk-costs,.wb-finance-tools')].map(e=>({id:e.id,open:e.open}));
   render();restoreForms($('#portal'),forms);
   for(const s of open){const e=document.getElementById(s.id);if(e)e.open=s.open;}
   if(query&&$('#sku-query')){$('#sku-query').value=query;$('#sku-query').dispatchEvent(new Event('input'));}
  }
 }catch(e){say('财务进度读取失败；后台任务可能仍在运行。'+e.message,true);}
 scheduleFinance();
}
async function loadCatalogue(q=state.catalogue.q||'',offset=state.catalogue.data?.offset||0){
 clearTimeout(catalogueTimer);const storeId=state.productStore,store=state.data.stores.find(s=>s.id===storeId);if(store?.mode!=='live'||!['ozon','wb'].includes(store.marketplace))return;
 const ticket=++catalogueRequest;let data,error;
 try{data=await api('/stores/'+encodeURIComponent(storeId)+'/catalogue?'+new URLSearchParams({q,offset}));}catch(e){error=e.message;}
 if(ticket!==catalogueRequest||storeId!==state.productStore||state.page!=='products')return;
 const previous=JSON.stringify(state.catalogue);state.catalogue={storeId,q,data:data||state.catalogue.data,error};
 if(!state.busy&&previous!==JSON.stringify(state.catalogue)){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}
 if(data?.status.state==='running')catalogueTimer=setTimeout(()=>loadCatalogue(q,offset),4000);
}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
async function live(force=false){const previous=JSON.stringify([state.live?.state,state.live?.data?.fetchedAt,state.live?.stale,state.live?.error,state.live?.lastAttempt?.finishedAt,state.live?.refreshAfter]);clearTimeout(liveTimer);try{const r=await fetch('/api/live'+(force?'?refresh=1':''),{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('local_api_unavailable');state.live=await r.json();const next=state.live.state==='syncing'?3000:Math.max(1000,Math.min(15*60000,Math.min(Date.parse(state.live.autoRefreshAt)||Infinity,Date.parse(state.live.refreshAfter)||Infinity)-Date.now()));liveTimer=setTimeout(()=>live(),Number.isFinite(next)?next:15*60000);}catch{state.live={...state.live,state:'error',stale:true,error:'local_api_unavailable'};liveTimer=setTimeout(()=>live(),30000);}if(['home','products'].includes(state.page)&&!state.busy&&previous!==JSON.stringify([state.live?.state,state.live?.data?.fetchedAt,state.live?.stale,state.live?.error,state.live?.lastAttempt?.finishedAt,state.live?.refreshAfter])){const forms=captureForms($('#portal')),query=$('#sku-query')?.value;render();restoreForms($('#portal'),forms);if(query&&$('#sku-query')){$('#sku-query').value=query;$('#sku-query').dispatchEvent(new Event('input'));}}}

try{await load();const transfer=location.hash.match(/^#migration\/([a-f0-9-]{36})$/);if(transfer&&state.data.jobs.some(j=>j.id===transfer[1])){state.job=await api('/jobs/'+transfer[1]);state.page='migration';}render();live();}catch(e){$('#portal').innerHTML=`<section class="card"><h2>需要本地服务</h2><p>${esc(e.message)}</p><code>npm start → http://127.0.0.1:4173</code><p>GitHub Pages 不连接真实店铺，也不保存 API 密钥。</p></section>`;}

async function loadWbPrices(){const focus=state.focus,store=state.data.stores.find(s=>s.id===focus?.storeId);if(store?.marketplace!=='wb'||store.mode!=='live')return;let result;try{result=await api('/stores/'+encodeURIComponent(store.id)+'/wb-prices?'+new URLSearchParams({nmID:focus.sku}));}catch(e){result={error:e.message};}if(state.focus!==focus||state.page!=='products')return;focus.wbPrices=result;if(!state.busy){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}}

async function loadWbInventory(){clearTimeout(inventoryTimer);const ticket=++inventoryRequest,focus=state.focus,store=state.data.stores.find(s=>s.id===focus?.storeId);if(store?.marketplace!=='wb'||store.mode!=='live'||state.page!=='products')return;let result;try{result=await api('/stores/'+encodeURIComponent(store.id)+'/wb-inventory?'+new URLSearchParams({nmID:focus.sku}));}catch(e){result={error:e.message};}if(ticket!==inventoryRequest||state.focus!==focus||state.page!=='products')return;focus.wbInventory=result;if(!state.busy){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}if(result.state==='reading')inventoryTimer=setTimeout(loadWbInventory,2000);}

function scheduleWbFinance(){const id=state.page==='home'?state.homeStore:state.page==='products'?state.focus?.storeId:null,key=state.page+'|'+id+'|'+(state.focus?.sku||''),active=id&&['reading','waiting'].includes(state.data.wbFinance?.[id]?.state);if(key!==wbFinanceScope||!active){clearTimeout(wbFinanceTimer);wbFinanceTimer=null;}wbFinanceScope=key;if(active&&!wbFinanceTimer)wbFinanceTimer=setTimeout(()=>{wbFinanceTimer=null;loadWbFinance();},2500);}
async function loadWbFinance(){clearTimeout(wbFinanceTimer);wbFinanceTimer=null;const ticket=++wbFinanceTicket,focus=state.focus,page=state.page,storeId=page==='home'?state.homeStore:page==='products'?focus?.storeId:null,store=state.data.stores.find(s=>s.id===storeId);if(store?.marketplace!=='wb'||store.mode!=='live')return;let result;try{result=await api('/stores/'+encodeURIComponent(storeId)+'/wb-finance'+(page==='products'?'?'+new URLSearchParams({sku:focus.sku,...focus.financePeriod}):''));}catch(e){result={state:'error',error:e.message};}if(ticket!==wbFinanceTicket||state.page!==page||(page==='home'?state.homeStore!==storeId:state.focus!==focus))return;state.data.wbFinance??={};state.data.wbFinance[storeId]=result;if(page==='products')focus.wbFinance=result;if(!state.busy){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}scheduleWbFinance();}

function scheduleWbAds(){const id=state.page==='home'?state.homeStore:state.page==='products'?state.focus?.storeId:null,key=state.page+'|'+id+'|'+(state.focus?.sku||''),active=id&&['reading','waiting'].includes(state.data.wbAds?.[id]?.state);if(key!==wbAdsScope||!active){clearTimeout(wbAdsTimer);wbAdsTimer=null;}wbAdsScope=key;if(active&&!wbAdsTimer)wbAdsTimer=setTimeout(()=>{wbAdsTimer=null;loadWbAds();},2500);}
async function loadWbAds(){clearTimeout(wbAdsTimer);wbAdsTimer=null;const ticket=++wbAdsTicket,focus=state.focus,page=state.page,id=page==='home'?state.homeStore:page==='products'?focus?.storeId:null,store=state.data.stores.find(s=>s.id===id);if(store?.marketplace!=='wb'||store.mode!=='live')return;let result;try{result=await api('/stores/'+encodeURIComponent(id)+'/wb-ads'+(page==='products'?'?'+new URLSearchParams({sku:focus.sku,...focus.financePeriod}):''));}catch(e){result={state:'error',error:e.message};}if(ticket!==wbAdsTicket||state.page!==page||(page==='home'?state.homeStore!==id:state.focus!==focus))return;state.data.wbAds??={};state.data.wbAds[id]=result;if(page==='products')focus.wbAds=result;if(!state.busy){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}scheduleWbAds();}

function scheduleWbErrors(){const job=state.page==='migration'?state.job:null,key=job?.id,reading=job?.wbListingErrors?.state==='reading',delay=(job?.wbListingErrors?.retryAt||0)-Date.now(),active=reading||delay>0;if(key!==wbErrorsScope||!active){clearTimeout(wbErrorsTimer);wbErrorsTimer=null;}wbErrorsScope=key;if(active&&!wbErrorsTimer)wbErrorsTimer=setTimeout(()=>{wbErrorsTimer=null;loadWbErrors();},reading?2500:Math.min(60000,Math.max(250,delay+100)));}
async function loadWbErrors(){const job=state.job,ticket=++wbErrorsTicket;if(state.page!=='migration'||!job)return;let result;try{result=await api('/stores/'+encodeURIComponent(job.storeId)+'/wb-listing-errors?'+new URLSearchParams({vendorCode:job.canonical.sku}));}catch(e){result={state:'error',error:e.message};}if(ticket!==wbErrorsTicket||state.page!=='migration'||state.job?.id!==job.id)return;state.job.wbListingErrors=result;if(!state.busy){const forms=captureForms($('#portal'));render();restoreForms($('#portal'),forms);}scheduleWbErrors();}

// Read progress automatically after submission. Never retries a write.
function scheduleOzonStatus(){
 const job=state.page==='migration'?state.job:null,id=job?.id;
 if(ozonPollScope!==id){clearTimeout(ozonStatusTimer);ozonStatusTimer=null;ozonPollScope=id;ozonPollCount=0;}
 const pending=job?.marketplace==='ozon'&&(job.imageRepair?.state==='accepted'||job.state==='submitted'||job.state==='imported'&&job.importResult?.platformStatus?.is_created===false)&&(job.imageRepair?.state==='accepted'||!(job.importResult?.errors||[]).length);
 if(!pending||ozonPollCount>=12){clearTimeout(ozonStatusTimer);ozonStatusTimer=null;return;}
 if(ozonStatusTimer)return;
 ozonStatusTimer=setTimeout(async()=>{ozonStatusTimer=null;if(state.busy){scheduleOzonStatus();return;}if(state.page!=='migration'||state.job?.id!==id)return;ozonPollCount++;
  try{const updated=await api('/jobs/'+id+'/sync',{});if(state.page==='migration'&&state.job?.id===id&&!state.busy){state.job=updated;render();}}
  catch{say('平台状态暂时无法读取；不会重新提交商品。',true);}
  scheduleOzonStatus();
 },5000);
}
